//! T32 residual (t3300): `dunks.json` is byte-compatible with the Python daemon's file for DUNK
//! STATE. Populated outbox and stuck state are not covered here; they are a follow-up.
//!
//! The fixture under `tests/fixtures/dunks/` is a SANITIZED whole-state file written by the
//! Python implementation (`dunk_core.Flock._save()`, regenerated by `make_python_fixture.py`):
//! synthetic pane ids, paths and text, one running dunk, every persisted dunk field, non-ASCII
//! text, and decided rows in decided order. Its outbox and stuck maps are empty by design. Restoring
//! it and saving again must reproduce the same bytes: insertion order kept, Python float reprs,
//! `ensure_ascii` escapes, no trailing newline.

use super::{status_runtime::StatusState, Flock};
use crate::config::Env;
use serde_json::{json, Value};

const PYTHON_WRITTEN: &[u8] =
    include_bytes!("../../tests/fixtures/dunks/python-written-dunks.json");

fn flock(dir: &std::path::Path) -> Flock {
    Flock::new(dir.join("launches.json"), dir.join("lanes.json"), true)
}

#[test]
fn python_written_dunks_file_round_trips_byte_identical() {
    let dir = tempfile::tempdir().unwrap();
    let executable = dir.path().join("daemon");
    std::fs::write(&executable, b"fixture").unwrap();
    let state_path = dir.path().join("dunks.json");
    std::fs::write(&state_path, PYTHON_WRITTEN).unwrap();
    let payload: Value = serde_json::from_slice(PYTHON_WRITTEN).unwrap();

    let flock = flock(dir.path());
    flock
        .attach_status_state(StatusState::at_start(
            "test",
            &state_path,
            executable,
            Env::default(),
        ))
        .unwrap();
    flock.restore_snapshot(&payload);

    // The restore really read the Python rows; a silent no-op restore would fail below too.
    assert_eq!(6, flock.dunks.list().len());
    assert_eq!(
        json!("status? \u{2014} reply briefly"),
        flock.dunks.get("d2").unwrap()["text"]
    );
    assert_eq!(
        json!("check \u{1F600} build"),
        flock.dunks.get("d4").unwrap()["text"]
    );
    // A running dunk whose deadline is still ahead keeps it on restore (no re-arm).
    assert_eq!(
        json!(4_102_444_800.25),
        flock.dunks.get("d1").unwrap()["next_send_at"]
    );

    flock.save().unwrap();
    let written = std::fs::read(&state_path).unwrap();
    let first_difference = PYTHON_WRITTEN
        .iter()
        .zip(&written)
        .position(|(expected, actual)| expected != actual)
        .unwrap_or(PYTHON_WRITTEN.len().min(written.len()));
    let expected_len = PYTHON_WRITTEN.len();
    let actual_len = written.len();
    assert!(
        written.as_slice() == PYTHON_WRITTEN,
        "a dunks.json saved by Rust must match the Python-written file byte for byte: \
         first difference at byte {first_difference} (python {expected_len} bytes, rust {actual_len})"
    );
}

#[test]
fn a_second_round_trip_is_stable() {
    let dir = tempfile::tempdir().unwrap();
    let executable = dir.path().join("daemon");
    std::fs::write(&executable, b"fixture").unwrap();
    let state_path = dir.path().join("dunks.json");
    let payload: Value = serde_json::from_slice(PYTHON_WRITTEN).unwrap();

    let first = flock(dir.path());
    first
        .attach_status_state(StatusState::at_start(
            "test",
            &state_path,
            executable.clone(),
            Env::default(),
        ))
        .unwrap();
    first.restore_snapshot(&payload);
    first.save().unwrap();
    let once = std::fs::read(&state_path).unwrap();

    let second = flock(dir.path());
    second
        .attach_status_state(StatusState::at_start(
            "test",
            &state_path,
            executable,
            Env::default(),
        ))
        .unwrap();
    second.restore_snapshot(&serde_json::from_slice(&once).unwrap());
    second.save().unwrap();
    assert_eq!(once, std::fs::read(&state_path).unwrap());
}
